const BACKUP_FILES = [
  ...Object.entries(EXPORT_SPECS).map(([name, spec]) => ({ name, title: spec.title })),
  ...BACKUP_EXTRA.map(([name, title]) => ({ name, title })),
];

function backupMine(viewer: Staff): ApprovalRow | undefined {
  expireStaleApprovals();
  return approvals
    .filter(
      (row) =>
        row.kind === "backup" &&
        row.requested_by === viewer.id &&
        ["pending", "approved"].includes(approvalStatus(row)),
    )
    .sort((a, b) => b.requested_at.localeCompare(a.requested_at))[0];
}

routes.push(
  {
    method: "GET",
    pattern: "hq/backup",
    auth: true,
    capability: "hq:admin",
    handler: ({ headers }) => {
      const found = caller(headers)!;
      const mine = backupMine(found.member);
      return ok({
        can_make: found.role === "owner",
        needs_approval: approvers("backup", found.member.id).length > 0,
        request: mine ? approvalView(mine, found.member) : null,
        recent: exportLedger
          .filter((row) => row.kind === "backup")
          .slice(0, 10)
          .map((row) => ({
            made_by: nameOf(row.staff_id),
            made_at: row.created_at,
            rows: row.rows,
            reason: row.reason,
          })),
        files: BACKUP_FILES,
        excluded: BACKUP_EXCLUDED,
      });
    },
  },
  {
    method: "POST",
    pattern: "hq/backup/request",
    auth: true,
    capability: "hq:admin",
    sudo: true,
    handler: ({ headers, body }) => {
      const found = caller(headers)!;
      if (found.role !== "owner") return refuse(403, "forbidden", { required_role: "owner" });
      const reason = String(body.reason ?? "")
        .trim()
        .slice(0, 400);
      if (reason.length < 8)
        return refuse(400, "malformed_request", { reason: "say what the backup is for" });
      if (approvers("backup", found.member.id).length === 0) return ok({ pending_approval: false });
      if (backupMine(found.member))
        return refuse(400, "malformed_request", {
          request: "you already have a backup waiting or ready to download",
        });
      return ok({
        pending_approval: true,
        approval: requestApproval("backup", found.member, {}, reason),
      });
    },
  },
  {
    method: "POST",
    pattern: "hq/backup/make",
    auth: true,
    capability: "hq:admin",
    sudo: true,
    handler: ({ headers, body }) => {
      const found = caller(headers)!;
      if (found.role !== "owner") return refuse(403, "forbidden", { required_role: "owner" });
      let approval: ApprovalRow | undefined;
      let reason: string;
      if (approvers("backup", found.member.id).length > 0) {
        approval = approvals.find((row) => row.id === String(body.approval_id ?? ""));
        if (!approval || approval.kind !== "backup") return refuse(404, "not_found");
        if (approval.requested_by !== found.member.id)
          return refuse(403, "forbidden", { reason: "not-yours" });
        const status = approvalStatus(approval);
        if (status !== "approved") {
          if (status === "expired") approval.status = "expired";
          return refuse(400, "malformed_request", { status: `${status}, not approved` });
        }
        reason = approval.reason;
      } else {
        reason = String(body.reason ?? "")
          .trim()
          .slice(0, 400);
        if (reason.length < 8)
          return refuse(400, "malformed_request", { reason: "say what the backup is for" });
      }
      const files = [
        ...Object.entries(EXPORT_SPECS).map(([name, spec]) => {
          const built = exportTable(name, headers, {}) as Exclude<
            ReturnType<typeof exportTable>,
            { errors: Record<string, string> }
          >;
          return {
            name,
            title: spec.title,
            columns: built.columns.map(([key, label, type]) => ({
              key,
              label,
              type: type ?? "text",
            })),
            table: built.records.map((record) => record.cells),
          };
        }),
        ...BACKUP_EXTRA.map(([name, title, build]) => {
          const built = build();
          return {
            name,
            title,
            columns: built.columns.map(([key, label, type]) => ({
              key,
              label,
              type: type ?? "text",
            })),
            table: built.rows,
          };
        }),
      ];
      const rows = files.reduce((sum, file) => sum + file.table.length, 0);
      audit("backup.made", found.member.id, "backup", approval?.id ?? "sole", reason, {
        files: files.length,
        rows,
        dual_control: approval ? "approved" : "sole_approver",
        approved_by: approval?.decided_by ?? "",
      });
      recordExport(found.member.id, "backup", "backup", rows, reason, null);
      if (approval) {
        approval.status = "done";
        approval.result_id = "backup";
      }
      return ok({
        generated_at: now(),
        made_by: found.member.display_name || found.member.email,
        approved_by: approval ? nameOf(approval.decided_by) : "",
        reason,
        rows,
        files,
        excluded: BACKUP_EXCLUDED,
      });
    },
  },
);

/**
 * Every column and record of a kind the caller may take, custom values filled in — the
 * service's export_routes.build without the view's ids, shared by an export and a backup.
 */
function exportTable(
  kind: string,
  headers: Record<string, string | string[] | undefined>,
  body: Record<string, unknown>,
):
  | { columns: Array<[string, string, string?]>; records: ExportRecord[]; fields: CfFieldRow[] }
  | { errors: Record<string, string> } {
  const spec = EXPORT_SPECS[kind]!;
  let records = spec.rows(headers);
  if (kind === "prospects") {
    const parsed = leadParseConditions(body.conditions);
    if (Object.keys(parsed.errors).length) return { errors: parsed.errors };
    const stageFilter = String(body.stage_filter ?? "");
    const needle = String(body.q ?? "")
      .trim()
      .toLowerCase();
    records = leadApply(
      leads
        .filter((row) => row.origin === "prospect")
        .map(leadView)
        .filter((view) => !stageFilter || view.stage === stageFilter)
        .filter(
          (view) =>
            !needle ||
            `${view.full_name} ${view.email} ${view.company_name} ${view.title} ${view.country} ${view.city}`
              .toLowerCase()
              .includes(needle),
        ),
      parsed.conditions,
    ).map((view) =>
      keyed(view.lead_id, [
        view.lead_id,
        view.email,
        view.full_name,
        view.title,
        view.company_name,
        view.firm_type,
        view.country,
        view.city,
        view.email_kind,
        view.verified_state,
        view.verified_detail,
        view.verified_at,
        view.fit_band,
        view.fit_score,
        view.stage,
        view.tags.join(", "),
        view.firm_domain,
        view.source_url,
      ]),
    );
  }
  // The custom fields this role may read, typed as the field is.
  const fields = exportCustomFields(kind, headers);
  const columns: Array<[string, string, string?]> = [
    ...spec.columns,
    ...fields.map(
      (field) =>
        [`custom.${field.field_key}`, field.label, EXPORT_CUSTOM_TYPES[field.kind] ?? "text"] as [
          string,
          string,
          string,
        ],
    ),
  ];
  if (fields.length)
    records = records.map((record) => ({
      id: record.id,
      cells: [
        ...record.cells,
        ...fields.map((field) =>
          exportCustomCell(field, customValues.get(cfKey(field.id, record.id)) ?? ""),
        ),
      ],
    }));
  return { columns, records, fields };
}

/** A stored custom value as its column's type, as the service's `_typed`. */
function exportCustomCell(field: CfFieldRow, value: string): ExportCell {
  if (field.kind === "checkbox") return Boolean(value);
  if (!value) return null;
  if (field.kind === "number") {
    const number = Number(value);
    return Number.isFinite(number) ? number : value;
  }
  if (field.kind === "date") return value.slice(0, 10);
  return cfDisplay(field, value);
}

// =====================================================================================
// The company's particulars, mirroring hq/company and hq/company/update: one record in
// the settings store, checked as the service checks it (shapes, a CIN's year and class,
// a PAN's fourth letter, the PAN inside a GSTIN and its Luhn mod 36 character), and the
// letterhead and the law's list worked out from it. Seeded with what is public only —
// the site, the address people write to, the city, who signs — never a number.
// =====================================================================================
const COMPANY_FIELDS = [
  "legal_name",
  "entity_type",
  "former_name",
  "name_changed_on",
  "registration_number",
  "incorporated_on",
  "pan",
  "gstin",
  "udyam",
  "dpiit",
  "registered_address",
  "operating_address",
  "phone",
  "email",
  "website",
  "signatory_name",
  "signatory_title",
  "document_note",
] as const;
type CompanyField = (typeof COMPANY_FIELDS)[number];
const COMPANY_LIMITS: Record<CompanyField, [number, boolean]> = {
  legal_name: [200, true],
  entity_type: [20, true],
  former_name: [200, true],
  name_changed_on: [10, true],
  registration_number: [24, true],
  incorporated_on: [10, true],
  pan: [10, true],
  gstin: [15, true],
  udyam: [19, true],
  dpiit: [20, true],
  registered_address: [400, false],
  operating_address: [400, false],
  phone: [40, true],
  email: [254, true],
  website: [200, true],
  signatory_name: [120, true],
  signatory_title: [120, true],
  document_note: [300, true],
};
const ENTITY_TYPES: Record<string, string> = {
  unregistered: "Not registered yet",
  proprietorship: "Sole proprietorship",
  partnership: "Partnership firm",
  llp: "Limited liability partnership",
  private_limited: "Private limited company",
  opc: "One person company",
  public_limited: "Public limited company",
};
const COMPANY_KINDS = ["private_limited", "opc", "public_limited"];
const CIN_CLASS: Record<string, string> = {
  PTC: "private_limited",
  OPC: "opc",
  PLC: "public_limited",
};
const PAN_HOLDER: Record<string, string> = {
  private_limited: "C",
  opc: "C",
  public_limited: "C",
  llp: "F",
  partnership: "F",
  proprietorship: "P",
};
const companySettings: Record<string, string> = {};
let companyUpdated: { at: string; by: string } | null = null;

function seedCompany() {
  for (const key of Object.keys(companySettings)) delete companySettings[key];
  companyUpdated = null;
  Object.assign(companySettings, {
    operating_address: "Jammu, India",
    email: "contact@quantifyterminal.com",
    website: "https://quantifyterminal.com",
    signatory_name: "Aaryan Saroha",
    signatory_title: "Founder and Chief Executive Officer",
  });
}
seedCompany();

function companyRecord(): Record<CompanyField, string> {
  return Object.fromEntries(
    COMPANY_FIELDS.map((key) => [key, companySettings[key] ?? ""]),
  ) as Record<CompanyField, string>;
}

function gstinCheck(first14: string): string {
  const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  let total = 0;
  [...first14].reverse().forEach((char, index) => {
    let value = alphabet.indexOf(char);
    if (index % 2 === 0) value *= 2;
    total += Math.floor(value / 36) + (value % 36);
  });
  return alphabet[(36 - (total % 36)) % 36]!;
}

function companyProblems(record: Record<string, string>, today: string): Record<string, string> {
  const errors: Record<string, string> = {};
  const kind = record.entity_type ?? "";
  if (kind && !ENTITY_TYPES[kind]) errors.entity_type = "choose one of the legal forms";
  for (const key of ["name_changed_on", "incorporated_on"]) {
    const value = record[key] ?? "";
    if (value && !/^\d{4}-\d{2}-\d{2}$/.test(value)) errors[key] = "a date, YYYY-MM-DD";
    else if (value && value > today) errors[key] = "cannot be in the future";
  }
  const legal = record.legal_name ?? "";
  if (
    legal &&
    /\b(limited|ltd\.?|llp|limited liability partnership|pvt\.?|private limited)\s*$/i.test(
      legal,
    ) &&
    ![...COMPANY_KINDS, "llp"].includes(kind)
  )
    errors.legal_name = "only a company or an LLP may end its name with Limited, Ltd, Pvt or LLP";
  const number = record.registration_number ?? "";
  if (number) {
    if (COMPANY_KINDS.includes(kind)) {
      if (!/^[LU]\d{5}[A-Z]{2}\d{4}[A-Z]{3}\d{6}$/.test(number))
        errors.registration_number = "a CIN is 21 characters, like U72900JK2026PTC012345";
      else {
        const klass = number.slice(12, 15);
        const year = Number(number.slice(8, 12));
        const incorporated = record.incorporated_on ?? "";
        if (CIN_CLASS[klass] && CIN_CLASS[klass] !== kind)
          errors.registration_number = `this CIN is a ${ENTITY_TYPES[CIN_CLASS[klass]!]!.toLowerCase()}'s (${klass}), not a ${ENTITY_TYPES[kind]!.toLowerCase()}'s`;
        else if (number.startsWith("L") && kind !== "public_limited")
          errors.registration_number =
            "an L at the start means a listed company; only a public company is listed";
        else if (incorporated && Number(incorporated.slice(0, 4)) !== year)
          errors.registration_number = `this CIN says incorporated in ${year}; the date of incorporation says ${incorporated.slice(0, 4)}`;
      }
    } else if (kind === "llp") {
      if (!/^[A-Z]{3}-\d{4}$/.test(number))
        errors.registration_number =
          "an LLPIN is three letters, a dash and four digits, like AAB-1234";
    } else if (["unregistered", "proprietorship", ""].includes(kind)) {
      errors.registration_number =
        "only a company, an LLP or a registered firm has a registration number";
    }
  }
  const pan = record.pan ?? "";
  if (pan) {
    if (!/^[A-Z]{5}\d{4}[A-Z]$/.test(pan))
      errors.pan = "a PAN is five letters, four digits and a letter, like AABCQ1234D";
    else if (PAN_HOLDER[kind] && pan[3] !== PAN_HOLDER[kind])
      errors.pan = `the fourth letter of a ${ENTITY_TYPES[kind]!.toLowerCase()}'s PAN is ${PAN_HOLDER[kind]}; this one is ${pan[3]}`;
  }
  const gstin = record.gstin ?? "";
  if (gstin) {
    const code = Number(gstin.slice(0, 2));
    if (!/^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(gstin))
      errors.gstin = "a GSTIN is 15 characters: state code, PAN, entity number, Z, check character";
    else if (!((code >= 1 && code <= 38) || code === 97 || code === 99))
      errors.gstin = `${gstin.slice(0, 2)} is not a GST state code`;
    else if (gstinCheck(gstin.slice(0, 14)) !== gstin[14])
      errors.gstin = "the last character does not check: a character is mistyped";
    else if (pan && /^[A-Z]{5}\d{4}[A-Z]$/.test(pan) && gstin.slice(2, 12) !== pan)
      errors.gstin = "the PAN inside this GSTIN is not the PAN above";
  }
  if (record.udyam && !/^UDYAM-[A-Z]{2}-\d{2}-\d{7}$/.test(record.udyam))
    errors.udyam = "a Udyam number reads UDYAM-JK-02-0001234";
  if (record.dpiit && !/^DIPP\d{3,8}$/.test(record.dpiit))
    errors.dpiit = "a DPIIT recognition number reads DIPP followed by digits";
  if (record.email && !/^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$/.test(record.email))
    errors.email = "an e-mail address";
  const phone = record.phone ?? "";
  const digits = phone.replace(/\D/g, "").length;
  if (phone && (!/^\+?[\d\s()-]+$/.test(phone) || digits < 7 || digits > 15))
    errors.phone = "digits, spaces, + ( ) and -, 7 to 15 digits";
  if (
    record.website &&
    !/^(?:https?:\/\/)?[a-z0-9-]+(?:\.[a-z0-9-]+)+(\/\S*)?$/i.test(record.website)
  )
    errors.website = "a web address, like quantifyterminal.com";
  if (record.name_changed_on && !record.former_name)
    errors.former_name = "the name it changed from";
  return errors;
}

function formerNamePrinted(record: Record<string, string>, today: string): string {
  if (!record.former_name || !record.name_changed_on) return "";
  const [y, m, d] = record.name_changed_on.split("-").map(Number) as [number, number, number];
  const until =
    m === 2 && d === 29
      ? `${y + 2}-02-28`
      : `${y + 2}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  return today < until ? record.former_name : "";
}

function companyRequirements(record: Record<string, string>, today: string) {
  const kind = record.entity_type ?? "";
  const item = (key: string, label: string, law: string, state: string, detail = "") => ({
    key,
    label,
    law,
    state,
    detail,
  });
  const have = (key: string) => (record[key] ? "met" : "missing");
  const legal = (record.legal_name ?? "").trim();
  if (COMPANY_KINDS.includes(kind)) {
    const law = "Companies Act 2013, s.12(3)(c)";
    const suffix = kind === "public_limited" ? "Limited" : "Private Limited";
    const ends =
      kind === "public_limited"
        ? /(limited|ltd\.?)$/i.test(legal)
        : /(private limited|pvt\.? ltd\.?)$/i.test(legal);
    const former = formerNamePrinted(record, today);
    return [
      item("legal_name", "Name", law, have("legal_name")),
      item("registered_address", "Registered office address", law, have("registered_address")),
      item(
        "registration_number",
        "Corporate Identity Number (CIN)",
        law,
        have("registration_number"),
      ),
      item("phone", "Telephone number", law, have("phone")),
      item("email", "E-mail address", law, have("email")),
      item("website", "Website, if there is one", law, record.website ? "met" : "optional"),
      item(
        "suffix",
        `The name ends with “${suffix}”`,
        "Companies Act 2013, s.4(1)(a)",
        legal && ends ? "met" : "missing",
      ),
      ...(kind === "opc"
        ? [
            item(
              "opc",
              "“(One Person Company)” with the name",
              "Companies Act 2013, s.12(3)",
              "met",
              "Printed by HQ with the name.",
            ),
          ]
        : []),
      item(
        "former_name",
        "A name changed in the last two years, beside the new one",
        law,
        former ? "met" : "not_applicable",
        former ? `Printing “${former}”.` : "No change of name in the last two years.",
      ),
    ];
  }
  if (kind === "llp") {
    const law = "LLP Act 2008, s.21";
    return [
      item("legal_name", "Name", law, have("legal_name")),
      item("registered_address", "Registered office address", law, have("registered_address")),
      item("registration_number", "Registration number (LLPIN)", law, have("registration_number")),
      item(
        "statement",
        "A statement that it is registered with limited liability",
        law,
        "met",
        "Printed by HQ under the name.",
      ),
      item(
        "suffix",
        "The name ends with “LLP” or “Limited Liability Partnership”",
        "LLP Act 2008, s.15",
        legal && /(llp|limited liability partnership)$/i.test(legal) ? "met" : "missing",
      ),
    ];
  }
  if (["partnership", "proprietorship", "unregistered"].includes(kind))
    return [
      item(
        "trading_name",
        "The trading name",
        "No statute sets this business's letters",
        "met",
        "Documents carry “Quantify Terminal” and nothing that suggests limited liability.",
      ),
    ];
  return [
    item(
      "entity_type",
      "The legal form",
      "Sets what the law asks documents to carry",
      "missing",
      "Choose it to see the list.",
    ),
  ];
}

function companyLetterhead(record: Record<string, string>, today: string) {
  const kind = record.entity_type ?? "";
  const legal = [...COMPANY_KINDS, "llp", "partnership"].includes(kind)
    ? (record.legal_name ?? "")
    : "";
  const numbers: string[] = [];
  if (record.registration_number)
    numbers.push(
      `${COMPANY_KINDS.includes(kind) ? "CIN" : kind === "llp" ? "LLPIN" : "Registration"} ${record.registration_number}`,
    );
  if (record.gstin) numbers.push(`GSTIN ${record.gstin}`);
  const address = (record.registered_address ?? "").replace(/\n/g, ", ");
  const operating = (record.operating_address ?? "").replace(/\n/g, ", ");
  const contact = [
    record.phone,
    record.email,
    (record.website ?? "").replace(/^https?:\/\//, ""),
  ].filter(Boolean);
  const former = COMPANY_KINDS.includes(kind) ? formerNamePrinted(record, today) : "";
  return {
    brand: "Quantify Terminal",
    name: legal || "Quantify Terminal",
    name_note: kind === "opc" ? "(One Person Company)" : "",
    former_name: former ? `Formerly ${former}` : "",
    trading_as:
      legal && legal.toLowerCase() !== "quantify terminal"
        ? `Quantify Terminal is a trading name of ${legal}`
        : "",
    liability:
      kind === "llp"
        ? "Registered with limited liability under the Limited Liability Partnership Act, 2008"
        : "",
    numbers: numbers.join(" · "),
    address:
      address && [...COMPANY_KINDS, "llp"].includes(kind)
        ? `Registered office: ${address}`
        : address || operating,
    contact: contact.join(" · "),
    signatory: { name: record.signatory_name ?? "", title: record.signatory_title ?? "" },
    note: record.document_note ?? "",
    complete: companyRequirements(record, today).every((item) => item.state !== "missing"),
  };
}

function companyPayload(viewerRole: string) {
  const today = now().slice(0, 10);
  const record = companyRecord();
  return {
    company: record,
    letterhead: companyLetterhead(record, today),
    requirements: companyRequirements(record, today),
    entity_types: Object.entries(ENTITY_TYPES).map(([value, label]) => ({ value, label })),
    updated_at: companyUpdated?.at ?? null,
    updated_by_name: companyUpdated
      ? (staff.find((member) => member.id === companyUpdated!.by)?.display_name ?? "")
      : "",
    can_edit: capsFor(viewerRole).includes("hq:admin"),
  };
}

routes.push(
  {
    method: "GET",
    pattern: "hq/company",
    auth: true,
    handler: ({ headers }) => ok(companyPayload(caller(headers)!.role)),
  },
  {
    method: "POST",
    pattern: "hq/company/update",
    auth: true,
    capability: "hq:admin",
    sudo: true,
    handler: ({ body, headers }) => {
      const today = now().slice(0, 10);
      const current = companyRecord();
      const writes: Record<string, string> = {};
      for (const key of COMPANY_FIELDS) {
        if (!(key in body)) continue;
        const [limit, single] = COMPANY_LIMITS[key];
        let value = String(body[key] ?? "").replace(/\r/g, "");
        value = single
          ? value.split(/\s+/).filter(Boolean).join(" ")
          : value
              .split("\n")
              .map((line) => line.split(/\s+/).filter(Boolean).join(" "))
              .filter(Boolean)
              .join("\n");
        value = value.slice(0, limit);
        if (["registration_number", "pan", "gstin", "udyam", "dpiit"].includes(key))
          value = value.toUpperCase().replace(/ /g, "");
        if (key === "email") value = value.toLowerCase();
        if (key === "website" && value) {
          const match = /^(?:https?:\/\/)?([a-z0-9-]+(?:\.[a-z0-9-]+)+)(\/\S*)?$/i.exec(value);
          if (match)
            value = `https://${match[1]!.toLowerCase()}${match[2] ?? ""}`.replace(/\/$/, "");
        }
        if (value !== current[key]) writes[key] = value;
      }
      const before = companyProblems(current, today);
      const after = companyProblems({ ...current, ...writes }, today);
      const made = Object.fromEntries(
        Object.entries(after).filter(([key, reason]) => before[key] !== reason),
      );
      if (Object.keys(made).length > 0) return refuse(400, "malformed_request", made);
      if (Object.keys(writes).length === 0)
        return refuse(400, "malformed_request", { body: "nothing to change" });
      Object.assign(companySettings, writes);
      const who = caller(headers)!;
      companyUpdated = { at: now(), by: who.member.id };
      audit("company.updated", who.member.id, "settings", "company");
      return ok(companyPayload(who.role));
    },
  },
);

// =====================================================================================
// Product: the product's administration, mirroring hq/product/whoami, the forwarded
// hq/product/<rest> routes and hq/staff/{staff_id}/account-link. As the service runs the
// Account API's own admin/<rest> handler as the staff member's linked account, this mock
// forwards to the console's mock (its admin fixtures) signed in as the linked persona —
// so start that mock too: MOCK_PORT=7072 npm run mock:api in the console repository.
// =====================================================================================
const PRODUCT_MOCK = (process.env.HQ_PRODUCT_MOCK_URL ?? "http://127.0.0.1:7072/api/v1").replace(
  /\/+$/,
  "",
);
/** The status `respond` uses to ask the server loop to forward asynchronously. */
const FORWARD = 299;
/** The console mock's personas: who may be linked, and their product role. */
const PRODUCT_ACCOUNTS: Record<string, { userId: string; role: string }> = {
  "owner@example.test": { userId: "4c7715ea-9ae3-4abd-b2f7-2d2c9a037d9b", role: "owner" },
  "admin@example.test": { userId: "8b2d4e61-1c3a-4f5b-8d9e-2a4c6b8d0f11", role: "admin" },
  "support@example.test": { userId: "5c1e7a93-2b4d-4e6f-9a1b-3c5d7e9f0a22", role: "support" },
  "user@example.test": { userId: "9d3f5b71-4c6e-4a8b-9c0d-1e3f5a7b9c33", role: "user" },
  "priya@example.test": { userId: "1a2b3c4d-5e6f-4a7b-8c9d-0e1f2a3b4c55", role: "user" },
  "leo@example.test": { userId: "2b3c4d5e-6f7a-4b8c-9d0e-1f2a3b4c5d66", role: "user" },
};
const PRODUCT_STAFF_ROLES = new Set([
  "owner",
  "admin",
  "support_manager",
  "support",
  "billing_manager",
  "auditor",
]);
/** staff id → linked console persona email. */
const productLinks = new Map<string, string>();
function seedProductLinks() {
  productLinks.clear();
  const byEmail = (email: string) => staff.find((member) => member.email === email)?.id;
  for (const [hq, product] of [
    ["owner@hq.test", "owner@example.test"],
    ["admin@hq.test", "admin@example.test"],
    ["support@hq.test", "support@example.test"],
  ] as const) {
    const id = byEmail(hq);
    if (id) productLinks.set(id, product);
  }
}
seedProductLinks();
function linkedAccountId(staffId: string): string | null {
  const email = productLinks.get(staffId);
  return email ? (PRODUCT_ACCOUNTS[email]?.userId ?? null) : null;
}

/** Every forwarded route, as the service's BRIDGED table lists them. */
const PRODUCT_BRIDGED: ReadonlyArray<[string, string]> = [
  ["hq/product/metrics", "GET"],
  ["hq/product/users", "GET"],
  ["hq/product/users/{user_id}", "GET"],
  ["hq/product/users/{user_id}/usage", "GET"],
  ["hq/product/users/{user_id}/entitlements", "GET"],
  ["hq/product/users/{user_id}/activation", "POST"],
  ["hq/product/users/{user_id}/role", "POST"],
  ["hq/product/users/{user_id}/subscription", "POST"],
  ["hq/product/users/{user_id}/entitlement", "POST"],
  ["hq/product/users/{user_id}/sessions/{session_id}/revoke", "POST"],
  ["hq/product/subscriptions", "GET"],
  ["hq/product/notifications", "GET"],
  ["hq/product/notifications/update", "POST"],
  ["hq/product/email", "GET"],
  ["hq/product/email/enqueue", "POST"],
  ["hq/product/audit-events/search", "GET"],
  ["hq/product/reports", "GET"],
  ["hq/product/reports/enqueue", "POST"],
  ["hq/product/reports/{report_id}/download", "GET"],
  ["hq/product/configuration", "GET"],
  ["hq/product/credentials", "GET"],
  ["hq/product/releases", "GET"],
  ["hq/product/role-report", "GET"],
  ["hq/product/staff", "GET"],
  ["hq/product/staff/{staff_user_id}", "POST"],
  ["hq/product/secrets", "GET"],
  ["hq/product/secrets/{slot}", "POST"],
  ["hq/product/secrets/{slot}/revoke", "POST"],
  ["hq/product/secrets/{slot}/restore", "POST"],
];

routes.push(
  {
    method: "GET",
    pattern: "hq/product/whoami",
    auth: true,
    capability: "product:access",
    handler: ({ headers }) => {
      const who = caller(headers)!;
      const email = productLinks.get(who.member.id);
      if (!email) return ok({ linked: false, reason: "account-not-linked", account: null });
      return {
        status: FORWARD,
        body: {
          kind: "whoami",
          email,
          staff: { staff_id: who.member.id, email: who.member.email, role: who.role },
          sudo_fresh: Boolean(who.session.sudo_until && who.session.sudo_until > now()),
        },
      };
    },
  },
  {
    method: "POST",
    pattern: "hq/staff/{staff_id}/account-link",
    auth: true,
    capability: "hq:admin",
    sudo: true,
    handler: ({ params, body, headers }) => {
      const who = caller(headers)!;
      if (who.role !== "owner") return refuse(403, "forbidden", { reason: "owner-only" });
      const target = staff.find((member) => member.id === params.staff_id);
      if (!target) return refuse(404, "not_found");
      const email = String(body.email ?? "")
        .trim()
        .toLowerCase();
      if (!email) {
        if (!productLinks.has(target.id))
          return refuse(400, "malformed_request", { email: "not linked" });
        productLinks.delete(target.id);
        audit("staff.account_unlinked", who.member.id, "staff", target.id);
        return ok({ staff_id: target.id, account: null });
      }
      const account = PRODUCT_ACCOUNTS[email];
      if (!account)
        return refuse(400, "malformed_request", {
          email: "no Quantify Terminal account has this address",
        });
      if (!PRODUCT_STAFF_ROLES.has(account.role))
        return refuse(400, "malformed_request", {
          email: "this account holds no staff role in the product; grant one first",
        });
      for (const [staffId, linked] of productLinks)
        if (linked === email && staffId !== target.id)
          return refuse(400, "malformed_request", {
            email: "already linked to another staff member",
          });
      productLinks.set(target.id, email);
      audit("staff.account_linked", who.member.id, "staff", target.id);
      return ok({
        staff_id: target.id,
        account: { user_id: account.userId, email, role: account.role },
      });
    },
  },
  ...PRODUCT_BRIDGED.map(([pattern, method]) => ({
    method,
    pattern,
    auth: true,
    capability: "product:access",
    sudo: method !== "GET",
    handler: ({ route, query, body, headers }: Parameters<Handler>[0]) => {
      const who = caller(headers)!;
      const email = productLinks.get(who.member.id);
      if (!email) return refuse(403, "forbidden", { reason: "account-not-linked" });
      return {
        status: FORWARD,
        body: {
          kind: "bridge",
          email,
          method,
          route: `admin/${route.slice("hq/product/".length)}`,
          query,
          body,
        },
      };
    },
  })),
);

const productTokens = new Map<string, string>();
async function productToken(email: string, fresh = false): Promise<string | null> {
  if (!fresh && productTokens.has(email)) return productTokens.get(email)!;
  const response = await fetch(`${PRODUCT_MOCK}/auth/login`, {
    method: "POST",
    headers: { "content-type": "application/json", "idempotency-key": randomUUID() },
    body: JSON.stringify({ email, password: "password-1234" }),
  });
  if (!response.ok) return null;
  const payload = (await response.json()) as { session?: { access_token?: string } };
  const token = payload.session?.access_token ?? null;
  if (token) productTokens.set(email, token);
  return token;
}

async function productCall(
  email: string,
  method: string,
  route: string,
  query: Record<string, string>,
  body: unknown,
) {
  const url = new URL(`${PRODUCT_MOCK}/${route}`);
  for (const [name, value] of Object.entries(query ?? {})) url.searchParams.set(name, value);
  for (const attempt of [false, true]) {
    const token = await productToken(email, attempt);
    if (!token) break;
    const response = await fetch(url, {
      method,
      headers: {
        authorization: `Bearer ${token}`,
        "content-type": "application/json",
        ...(method === "POST" ? { "idempotency-key": randomUUID() } : {}),
      },
      body: method === "POST" ? JSON.stringify(body ?? {}) : null,
    });
    // A restarted console mock forgets its tokens: sign in again once.
    if (response.status === 401 && !attempt) continue;
    return { status: response.status, body: (await response.json()) as Record<string, unknown> };
  }
  throw new Error("product mock refused the sign-in");
}

/** The asynchronous half: forward to the console's mock as the linked persona. */
async function forwardProduct(
  request: Record<string, unknown>,
): Promise<{ status: number; body: unknown }> {
  try {
    const email = String(request.email);
    if (request.kind === "whoami") {
      const me = await productCall(email, "GET", "me", {}, null);
      if (me.status !== 200) return refuse(503, "upstream_unavailable");
      const { ok: _ok, correlation_id: _correlation, ...rest } = me.body as Record<string, unknown>;
      void _ok;
      void _correlation;
      const role = (rest.role as { effective?: string } | undefined)?.effective ?? "user";
      const user = rest.user as { user_id: string; email: string };
      if (!PRODUCT_STAFF_ROLES.has(role))
        return ok({ linked: false, reason: "linked-account-not-staff", account: null });
      return ok({
        linked: true,
        reason: "",
        account: {
          user_id: user.user_id,
          email: user.email,
          role,
          capabilities: rest.capabilities,
        },
        me: rest,
        staff: request.staff,
        sudo_fresh: request.sudo_fresh,
      });
    }
    const answer = await productCall(
      email,
      String(request.method),
      String(request.route),
      (request.query as Record<string, string>) ?? {},
      request.body,
    );
    return answer;
  } catch {
    return refuse(503, "upstream_unavailable", { dependency: "product-mock" });
  }
}

