routes.push(
  {
    method: "GET",
    pattern: "hq/quotes",
    auth: true,
    capability: "revenue:read",
    handler: ({ query, headers }) => {
      const view = String(query.view || "open");
      if (!["open", "waiting", "mine", "all"].includes(view))
        return qBad({ view: "open, waiting, mine, all" });
      const me = caller(headers)?.member.id ?? "";
      const counts = { open: 0, waiting: 0, mine: 0, all: 0 };
      const views = [];
      for (const row of quoteRows) {
        const item = qView(row, headers, false);
        const matches: Record<string, boolean> = {
          open: ![...Q_FINAL, "expired"].includes(item.state),
          waiting: item.waiting_on_you,
          mine: row.created_by === me,
          all: true,
        };
        for (const key of Object.keys(counts) as Array<keyof typeof counts>)
          counts[key] += Number(matches[key]);
        if (matches[view]) views.push(item);
      }
      const order: Record<string, number> = {
        pending_approval: 0,
        changes_requested: 1,
        approved: 2,
        draft: 3,
        published: 4,
        expired: 5,
      };
      views.sort(
        (a, b) =>
          Number(!a.waiting_on_you) - Number(!b.waiting_on_you) ||
          (order[a.state] ?? 9) - (order[b.state] ?? 9) ||
          a.number.localeCompare(b.number),
      );
      return ok({ quotes: views, view, counts });
    },
  },
  {
    method: "GET",
    pattern: "hq/quotes/{quote_id}",
    auth: true,
    capability: "revenue:read",
    handler: ({ params, headers }) => {
      const row = quoteRows.find((item) => item.id === params.quote_id);
      if (!row) return refuse(404, "not_found");
      return ok({
        quote: qView(row, headers, true),
        plans: qPlanChoices(),
        peer_above: Q_PEER_ABOVE,
        admin_above: Q_ADMIN_ABOVE,
      });
    },
  },
  {
    method: "GET",
    pattern: "hq/deals/{deal_id}/quotes",
    auth: true,
    capability: "revenue:read",
    handler: ({ params, headers }) => {
      const deal = deals.find((item) => item.id === params.deal_id);
      if (!deal) return refuse(404, "not_found");
      return ok({
        quotes: quoteRows
          .filter((row) => row.deal_id === deal.id)
          .sort((a, b) => b.number.localeCompare(a.number))
          .map((row) => qView(row, headers, false)),
        plans: qPlanChoices(),
        currency: deal.currency,
        can_create: hasCap(headers, "deals:write") && deal.status === "open",
        peer_above: Q_PEER_ABOVE,
        admin_above: Q_ADMIN_ABOVE,
      });
    },
  },
  {
    method: "POST",
    pattern: "hq/deals/{deal_id}/quotes/create",
    auth: true,
    capability: "deals:write",
    handler: ({ params, body, headers }) => {
      const deal = deals.find((item) => item.id === params.deal_id);
      if (!deal) return refuse(404, "not_found");
      if (deal.status !== "open") return qBad({ deal_id: "a quote is made on an open deal" });
      const dealPlan = plans.find((plan) => plan.key === deal.plan_key);
      const currency = String(
        body.currency || dealPlan?.currency || deal.currency || "USD",
      ).toUpperCase();
      if (!/^[A-Z]{3}$/.test(currency)) return qBad({ currency: "a three-letter code, like USD" });
      const id = randomUUID();
      let lines: QuoteLineRow[] = [];
      if ("lines" in body) {
        const parsed = qParseLines(body.lines, currency, new Map(), id);
        if (!Array.isArray(parsed)) return parsed;
        lines = parsed;
      } else if (dealPlan && !dealPlan.archived && dealPlan.currency === currency) {
        const parsed = qParseLines(
          [{ plan_key: dealPlan.key, quantity: Math.max(deal.seats || 1, dealPlan.min_seats) }],
          currency,
          new Map(),
          id,
        );
        if (Array.isArray(parsed)) lines = parsed;
      }
      const term = qTerm(body.term_months ?? 12);
      if (term === null) return qBad({ term_months: "1 to 60 months" });
      const valid = qValidUntil(body.valid_until || addDaysIso(todayIso(), 30));
      if (typeof valid !== "string") return valid;
      const me = caller(headers)?.member.id ?? "";
      const row: QuoteRow = {
        id,
        deal_id: deal.id,
        number: qNextNumber(),
        title:
          String(body.title ?? "")
            .trim()
            .slice(0, 160) || deal.name,
        currency,
        term_months: term,
        valid_until: valid,
        terms: String(body.terms ?? "")
          .trim()
          .slice(0, 4000),
        status: "draft",
        is_primary: !quoteRows.some((item) => item.deal_id === deal.id && item.is_primary),
        approval_tier: qTier(lines)[0],
        submitted_by: null,
        submitted_at: null,
        decided_by: null,
        decided_at: null,
        decision_note: "",
        published_by: null,
        published_at: null,
        accepted_at: null,
        signer_name: "",
        signer_email: "",
        signed_on: null,
        signature_ref: "",
        declined_reason: "",
        created_by: me,
        created_at: now(),
        updated_at: now(),
      };
      quoteRows.push(row);
      quoteLines.push(...lines);
      audit("quote.created", me || null, "quote", id);
      return ok({ quote: qView(row, headers, true) });
    },
  },
  {
    method: "POST",
    pattern: "hq/quotes/{quote_id}/update",
    auth: true,
    capability: "deals:write",
    handler: ({ params, body, headers }) => {
      const row = quoteRows.find((item) => item.id === params.quote_id);
      if (!row) return refuse(404, "not_found");
      const state = qState(row);
      if (!Q_EDITABLE.includes(state))
        return qBad({
          status: `${(Q_LABELS[state] ?? state).toLowerCase()}: revise it to change it`,
        });
      const next: Partial<QuoteRow> = {};
      if ("title" in body) {
        const title = String(body.title ?? "")
          .trim()
          .slice(0, 160);
        if (!title) return qBad({ title: "cannot be empty" });
        next.title = title;
      }
      if ("currency" in body) {
        const currency = String(body.currency ?? "")
          .trim()
          .toUpperCase();
        if (!/^[A-Z]{3}$/.test(currency))
          return qBad({ currency: "a three-letter code, like USD" });
        next.currency = currency;
      }
      if ("term_months" in body) {
        const term = qTerm(body.term_months);
        if (term === null) return qBad({ term_months: "1 to 60 months" });
        next.term_months = term;
      }
      if ("valid_until" in body) {
        const valid = qValidUntil(body.valid_until);
        if (typeof valid !== "string") return valid;
        next.valid_until = valid;
      }
      if ("terms" in body)
        next.terms = String(body.terms ?? "")
          .trim()
          .slice(0, 4000);
      const oldLines = qLinesOf(row.id);
      const currency = next.currency ?? row.currency;
      let newLines: QuoteLineRow[] | null = null;
      if ("lines" in body || (next.currency && next.currency !== row.currency)) {
        const raw =
          "lines" in body
            ? body.lines
            : oldLines.map((line) => ({
                line_id: line.id,
                plan_key: line.plan_key,
                kind: line.kind,
                description: line.description,
                quantity: line.quantity,
                unit_price: String(line.unit_price),
              }));
        const parsed = qParseLines(
          raw,
          currency,
          new Map(oldLines.map((line) => [line.id, line])),
          row.id,
        );
        if (!Array.isArray(parsed)) return parsed;
        newLines = parsed;
      }
      const priced = (lines: QuoteLineRow[]) =>
        JSON.stringify(
          lines.map((line) => [
            line.kind,
            line.plan_key,
            line.description,
            line.quantity,
            line.list_unit,
            line.unit_price,
          ]),
        );
      const linesChanged = newLines !== null && priced(newLines) !== priced(oldLines);
      const changed = (Object.keys(next) as Array<keyof QuoteRow>).filter(
        (key) => next[key] !== row[key],
      );
      if (!changed.length && !linesChanged) return qBad({ fields: "nothing to change" });
      const termsChanged =
        linesChanged ||
        changed.some((key) => ["currency", "term_months", "valid_until", "terms"].includes(key));
      const cancelled = termsChanged && ["pending_approval", "approved"].includes(row.status);
      for (const key of changed) Object.assign(row, { [key]: next[key] });
      if (linesChanged && newLines) {
        for (let index = quoteLines.length - 1; index >= 0; index -= 1)
          if (quoteLines[index]!.quote_id === row.id) quoteLines.splice(index, 1);
        quoteLines.push(...newLines);
        row.approval_tier = qTier(newLines)[0];
      }
      if (cancelled)
        Object.assign(row, {
          status: "draft",
          submitted_by: null,
          submitted_at: null,
          decided_by: null,
          decided_at: null,
          decision_note: "",
        });
      row.updated_at = now();
      audit("quote.updated", caller(headers)?.member.id ?? null, "quote", row.id);
      return ok({ quote: qView(row, headers, true), approval_cancelled: cancelled });
    },
  },
  {
    method: "POST",
    pattern: "hq/quotes/{quote_id}/act",
    auth: true,
    capability: "deals:write",
    handler: ({ params, body, headers }) => {
      const row = quoteRows.find((item) => item.id === params.quote_id);
      if (!row) return refuse(404, "not_found");
      const who = caller(headers)?.member;
      const me = who?.id ?? "";
      const role = who?.role ?? "";
      const action = String(body.action ?? "");
      const actions = [
        "submit",
        "recall",
        "approve",
        "request_changes",
        "publish",
        "accept",
        "decline",
        "withdraw",
        "make_primary",
        "revise",
      ];
      if (!actions.includes(action)) return qBad({ action: actions.join(", ") });
      const state = qState(row);
      const lines = qLinesOf(row.id);
      const can = qAbilities(role, me, row, state, lines.length) as Record<string, boolean>;
      const deal = deals.find((item) => item.id === row.deal_id);
      const label = `${row.number} · ${deal?.name ?? ""}`;
      const link = `/deals/${row.deal_id}/quotes/${row.id}`;
      if (
        ["approve", "request_changes"].includes(action) &&
        state === "pending_approval" &&
        !can[action]
      )
        return refuse(403, "forbidden", {
          action:
            me === row.created_by || me === row.submitted_by
              ? "someone other than its author approves it"
              : "above 25 % an owner or admin approves it",
        });
      if (action !== "make_primary" && !can[action]) {
        const why: Record<string, string> = {
          submit: ["draft", "changes_requested"].includes(state)
            ? "it needs no approval, or has no lines"
            : "only a draft is sent for approval",
          recall: "only a quote waiting for approval is recalled, by its author",
          approve: "only a quote waiting for approval is approved",
          request_changes: "only a quote waiting for approval is sent back",
          publish: ["draft", "changes_requested", "pending_approval"].includes(state)
            ? "it needs approval first"
            : "it cannot be sent now",
          accept:
            state === "expired"
              ? `it expired on ${row.valid_until}; revise it`
              : "only a sent quote is signed",
          decline: "only a sent quote is declined",
          withdraw: "it is over",
          revise: "only a sent, expired, declined or withdrawn quote is revised",
        };
        return qBad({ status: why[action] ?? "not now" });
      }
      const extra: Record<string, unknown> = {};
      if (action === "submit") {
        const approvers = qApprovers({ ...row, submitted_by: me });
        if (!approvers.length)
          return qBad({ approval_tier: "nobody else can approve it; ask an owner to" });
        Object.assign(row, {
          status: "pending_approval",
          submitted_by: me,
          submitted_at: now(),
          decided_by: null,
          decided_at: null,
          decision_note: "",
        });
        inboxNotify({
          recipients: approvers.map((item) => item.staff_id),
          subject_type: "quote",
          subject_id: row.id,
          subject_label: label,
          reason: "review",
          summary: `${nameOf(me)} asks you to approve ${row.number}.`,
          actor_id: me,
          link_path: link,
        });
      } else if (action === "recall") {
        Object.assign(row, { status: "draft", submitted_by: null, submitted_at: null });
      } else if (action === "approve" || action === "request_changes") {
        const note = String(body.note ?? "")
          .trim()
          .slice(0, 1000);
        if (action === "request_changes" && !note) return qBad({ note: "what should change" });
        Object.assign(row, {
          status: action === "approve" ? "approved" : "changes_requested",
          decided_by: me,
          decided_at: now(),
          decision_note: note,
        });
        inboxNotify({
          recipients: [row.submitted_by ?? row.created_by],
          subject_type: "quote",
          subject_id: row.id,
          subject_label: label,
          reason: "state",
          summary: `${nameOf(me)} ${action === "approve" ? "approved" : "asked for changes to"} ${row.number}.${note ? ` ${note}` : ""}`,
          actor_id: me,
          link_path: link,
        });
      } else if (action === "publish") {
        if (!row.valid_until || row.valid_until < todayIso())
          return qBad({ valid_until: "today or later; change it first" });
        Object.assign(row, { status: "published", published_by: me, published_at: now() });
      } else if (action === "accept") {
        const signer = String(body.signer_name ?? "")
          .trim()
          .slice(0, 160);
        if (!signer) return qBad({ signer_name: "who signed it" });
        const email = String(body.signer_email ?? "")
          .trim()
          .slice(0, 254);
        if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))
          return qBad({ signer_email: "an email address" });
        const signedOn = String(body.signed_on || todayIso());
        if (!/^\d{4}-\d{2}-\d{2}$/.test(signedOn)) return qBad({ signed_on: "a date, YYYY-MM-DD" });
        if (signedOn > todayIso()) return qBad({ signed_on: "cannot be in the future" });
        if (row.published_at && signedOn < row.published_at.slice(0, 10))
          return qBad({ signed_on: "not before it was sent" });
        Object.assign(row, {
          status: "accepted",
          accepted_at: now(),
          signer_name: signer,
          signer_email: email,
          signed_on: signedOn,
          signature_ref: String(body.signature_ref ?? "")
            .trim()
            .slice(0, 400),
        });
        extra.deal_updated = qAfterAccept(row, lines, me || null);
      } else if (action === "decline") {
        const reason = String(body.reason ?? "")
          .trim()
          .slice(0, 400);
        if (!reason) return qBad({ reason: "why they declined" });
        Object.assign(row, { status: "declined", declined_reason: reason });
      } else if (action === "withdraw") {
        Object.assign(row, { status: "withdrawn", is_primary: false });
      } else if (action === "make_primary") {
        if (["declined", "withdrawn"].includes(state))
          return qBad({ status: "a declined or withdrawn quote is not the deal's quote" });
        for (const other of quoteRows)
          if (other.deal_id === row.deal_id) other.is_primary = other.id === row.id;
      } else if (action === "revise") {
        const copy: QuoteRow = {
          ...row,
          id: randomUUID(),
          number: qNextNumber(),
          status: "draft",
          is_primary: false,
          valid_until: addDaysIso(todayIso(), 30),
          submitted_by: null,
          submitted_at: null,
          decided_by: null,
          decided_at: null,
          decision_note: "",
          published_by: null,
          published_at: null,
          accepted_at: null,
          signer_name: "",
          signer_email: "",
          signed_on: null,
          signature_ref: "",
          declined_reason: "",
          created_by: me,
          created_at: now(),
          updated_at: now(),
        };
        quoteRows.push(copy);
        quoteLines.push(...lines.map((line) => ({ ...line, id: randomUUID(), quote_id: copy.id })));
        audit("quote.revised", me || null, "quote", copy.id);
        return ok({ quote: qView(copy, headers, true) });
      }
      row.updated_at = now();
      audit(`quote.${action}`, me || null, "quote", row.id);
      return ok({ quote: qView(row, headers, true), ...extra });
    },
  },
  {
    method: "GET",
    pattern: "hq/deals/{deal_id}/plan",
    auth: true,
    capability: "deals:read",
    handler: ({ params, headers }) => {
      const deal = deals.find((item) => item.id === params.deal_id);
      if (!deal) return refuse(404, "not_found");
      return ok(qPlanPayload(deal, headers));
    },
  },
  {
    method: "POST",
    pattern: "hq/deals/{deal_id}/plan/act",
    auth: true,
    capability: "deals:write",
    handler: ({ params, body, headers }) => {
      const deal = deals.find((item) => item.id === params.deal_id);
      if (!deal) return refuse(404, "not_found");
      const me = caller(headers)?.member.id ?? "";
      const action = String(body.action ?? "");
      const steps = planSteps
        .filter((row) => row.deal_id === deal.id)
        .sort((a, b) => a.position - b.position);
      const fields = (
        creating: boolean,
      ): Partial<PlanStepRow> | { status: number; body: unknown } => {
        const out: Partial<PlanStepRow> = {};
        if (creating || "title" in body) {
          const title = String(body.title ?? "")
            .trim()
            .slice(0, 200);
          if (!title) return qBad({ title: "what happens at this step" });
          out.title = title;
        }
        if (creating || "side" in body) {
          const side = String(body.side || "us");
          if (side !== "us" && side !== "them") return qBad({ side: "us or them" });
          out.side = side;
        }
        if (creating || "due_on" in body) {
          const due = String(body.due_on ?? "").trim();
          if (due && !/^\d{4}-\d{2}-\d{2}$/.test(due))
            return qBad({ due_on: "a date, YYYY-MM-DD" });
          out.due_on = due || null;
        }
        if (creating || "owner_staff_id" in body) {
          const owner =
            String(body.owner_staff_id ?? "")
              .trim()
              .toLowerCase() || null;
          if (owner && !staff.some((member) => member.id === owner))
            return qBad({ owner_staff_id: "choose someone on the team" });
          out.owner_staff_id = owner;
        }
        if (creating || "contact_name" in body)
          out.contact_name = String(body.contact_name ?? "")
            .trim()
            .slice(0, 160);
        if (creating || "notes" in body)
          out.notes = String(body.notes ?? "")
            .trim()
            .slice(0, 1000);
        return out;
      };
      if (action === "template") {
        if (steps.length) return qBad({ action: "the plan has steps; add to it instead" });
        const today = todayIso();
        const anchor =
          deal.expected_close_date && deal.expected_close_date > today
            ? deal.expected_close_date
            : addDaysIso(today, 30);
        Q_TEMPLATE.forEach(([title, side, days], position) => {
          const due = addDaysIso(anchor, days);
          planSteps.push({
            id: randomUUID(),
            deal_id: deal.id,
            position,
            title,
            side,
            owner_staff_id: side === "us" ? deal.owner_staff_id || me : null,
            contact_name: "",
            due_on: due < today ? today : due,
            done_at: null,
            done_by: null,
            notes: "",
            created_at: now(),
          });
        });
      } else if (action === "add") {
        if (steps.length >= 40) return qBad({ action: "a plan has at most 40 steps" });
        const made = fields(true);
        if ("status" in made && "body" in made) return made as { status: number; body: unknown };
        planSteps.push({
          id: randomUUID(),
          deal_id: deal.id,
          position: (steps.at(-1)?.position ?? -1) + 1,
          title: "",
          side: "us",
          owner_staff_id: null,
          contact_name: "",
          due_on: null,
          notes: "",
          ...(made as Partial<PlanStepRow>),
          done_at: null,
          done_by: null,
          created_at: now(),
        });
      } else if (["edit", "done", "reopen", "remove", "move"].includes(action)) {
        const step = steps.find((row) => row.id === String(body.step_id ?? "").toLowerCase());
        if (!step) return refuse(404, "not_found");
        if (action === "edit") {
          const made = fields(false);
          if ("status" in made && "body" in made) return made as { status: number; body: unknown };
          if (!Object.keys(made).length) return qBad({ fields: "nothing to change" });
          Object.assign(step, made);
        } else if (action === "done") {
          if (step.done_at) return qBad({ step_id: "already done" });
          Object.assign(step, { done_at: now(), done_by: me });
        } else if (action === "reopen") {
          if (!step.done_at) return qBad({ step_id: "not done" });
          Object.assign(step, { done_at: null, done_by: null });
        } else if (action === "remove") {
          planSteps.splice(planSteps.indexOf(step), 1);
        } else {
          const direction = String(body.direction ?? "");
          if (direction !== "up" && direction !== "down") return qBad({ direction: "up or down" });
          const index = steps.indexOf(step);
          const other = direction === "up" ? index - 1 : index + 1;
          if (other < 0 || other >= steps.length)
            return qBad({ direction: "it is already at that end" });
          [steps[index], steps[other]] = [steps[other]!, steps[index]!];
          steps.forEach((row, position) => (row.position = position));
        }
      } else return qBad({ action: "template, add, edit, done, reopen, remove, move" });
      audit(`plan_step.${action}`, me || null, "deal", deal.id);
      return ok(qPlanPayload(deal, headers));
    },
  },
);

// --- references and business reviews (mirrors account_api/hq/references.py and relationship_routes.py) ---

type ReferenceRow = {
  id: string;
  company_id: string;
  person_id: string | null;
  contact_name: string;
  kinds: string[];
  scope: string;
  given_on: string;
  expires_on: string;
  evidence: string;
  calls_per_quarter: number;
  status: string;
  withdrawn_on: string | null;
  withdrawn_reason: string;
  recorded_by: string;
  created_at: string;
};
type ReferenceUseRow = {
  id: string;
  reference_id: string;
  kind: string;
  deal_id: string | null;
  used_on: string;
  note: string;
  staff_id: string;
};
type BusinessReviewRow = {
  id: string;
  company_id: string;
  period_start: string;
  period_end: string;
  title: string;
  snapshot: Record<string, unknown>;
  snapshot_at: string;
  goals: string;
  wins: string;
  risks: string;
  actions: string;
  attendees: string;
  held_on: string | null;
  status: string;
  finalised_by: string | null;
  finalised_at: string | null;
  created_by: string;
  updated_at: string;
};

const REF_KINDS: Record<string, string> = {
  call: "Reference calls",
  logo: "Logo on our site and decks",
  quote: "Quoted by name",
  case_study: "A case study",
};
const REF_PUBLIC: Record<string, string> = {
  logo: "logo",
  quote: "quote",
  case_study: "case study",
};
const referenceRows: ReferenceRow[] = [];
const referenceUses: ReferenceUseRow[] = [];
const businessReviews: BusinessReviewRow[] = [];
const relBad = (details: Record<string, string>) => refuse(400, "malformed_request", details);

function relQuarter(day: string): [string, string] {
  const year = Number(day.slice(0, 4));
  const first = 3 * Math.floor((Number(day.slice(5, 7)) - 1) / 3) + 1;
  const start = `${year}-${String(first).padStart(2, "0")}-01`;
  return [start, addDaysIso(addMonthsIso(start, 3), -1)];
}
const relQuarterLabel = (day: string) =>
  `Q${Math.floor((Number(day.slice(5, 7)) - 1) / 3) + 1} ${day.slice(0, 4)}`;
function relLastQuarter(day: string): [string, string] {
  return relQuarter(addDaysIso(relQuarter(day)[0], -1));
}
function relTitle(start: string, end: string) {
  const [qs, qe] = relQuarter(start);
  if (qs === start && qe === end) return `Business review, ${relQuarterLabel(start)}`;
  return `Business review, ${pvDay(start)} to ${pvDay(end)}`;
}
function relState(row: ReferenceRow) {
  if (row.status === "withdrawn") return "withdrawn";
  const day = todayIso();
  if (row.expires_on < day) return "expired";
  if (finDays(day, row.expires_on) <= 30) return "expiring";
  return "active";
}
function relCallsIn(uses: ReferenceUseRow[], day: string) {
  const [start, end] = relQuarter(day);
  return uses.filter((use) => use.kind === "call" && use.used_on >= start && use.used_on <= end)
    .length;
}
function relView(row: ReferenceRow) {
  const uses = referenceUses.filter((use) => use.reference_id === row.id);
  const person = row.person_id ? people.find((item) => item.id === row.person_id) : undefined;
  return {
    reference_id: row.id,
    company_id: row.company_id,
    company_name: companies.find((item) => item.id === row.company_id)?.name ?? "",
    person_id: row.person_id,
    person_name: person?.full_name || row.contact_name,
    kinds: row.kinds,
    kind_labels: row.kinds.map((kind) => REF_KINDS[kind] ?? kind),
    scope: row.scope,
    given_on: row.given_on,
    expires_on: row.expires_on,
    evidence: row.evidence,
    state: relState(row),
    calls_per_quarter: row.calls_per_quarter,
    calls_this_quarter: relCallsIn(uses, todayIso()),
    uses: uses.length,
    last_used_on:
      uses
        .map((use) => use.used_on)
        .sort()
        .at(-1) ?? null,
    withdrawn_on: row.withdrawn_on,
    withdrawn_reason: row.withdrawn_reason,
    recorded_by_name: nameOf(row.recorded_by),
    created_at: row.created_at,
  };
}
function relDetail(row: ReferenceRow) {
  return {
    reference: relView(row),
    uses: referenceUses
      .filter((use) => use.reference_id === row.id)
      .sort((a, b) => b.used_on.localeCompare(a.used_on))
      .map((use) => ({
        kind: use.kind,
        kind_label: REF_KINDS[use.kind] ?? use.kind,
        deal_id: use.deal_id,
        deal_name: use.deal_id ? (deals.find((deal) => deal.id === use.deal_id)?.name ?? "") : "",
        used_on: use.used_on,
        note: use.note,
        staff_name: nameOf(use.staff_id),
      })),
  };
}
function relKinds(value: unknown): string[] | null {
  const raw = Array.isArray(value) ? value : String(value ?? "").split(",");
  const chosen = raw.map((item) => String(item).trim()).filter(Boolean);
  if (!chosen.length || chosen.some((kind) => !(kind in REF_KINDS))) return null;
  return Object.keys(REF_KINDS).filter((kind) => chosen.includes(kind));
}
function relDates(
  body: Record<string, unknown>,
): [string, string] | { status: number; body: unknown } {
  const given = String(body.given_on || todayIso());
  if (!/^\d{4}-\d{2}-\d{2}$/.test(given)) return relBad({ given_on: "a date, YYYY-MM-DD" });
  if (given > todayIso()) return relBad({ given_on: "cannot be in the future" });
  const expires = String(body.expires_on || addDaysIso(given, 365));
  if (!/^\d{4}-\d{2}-\d{2}$/.test(expires) || expires <= given || finDays(given, expires) > 3 * 366)
    return relBad({ expires_on: "after the day it was given, and within three years" });
  return [given, expires];
}

function relSnapshot(companyId: string, start: string, end: string) {
  const asOf = end < todayIso() ? end : todayIso();
  const rows = (csActiveContracts().get(companyId) ?? []).filter((row) => row.starts_on <= asOf);
  const seats = rows.reduce((total, row) => total + row.seats, 0);
  const logins = csLogins.get(companyId) ?? [];
  const next = rows
    .filter((row) => row.renews_on)
    .sort((a, b) => a.renews_on!.localeCompare(b.renews_on!))[0];
  const accounts = new Set(
    people
      .filter((person) => person.company_id === companyId && person.account_user_id)
      .map((person) => person.account_user_id),
  );
  let ticketFigures: Record<string, unknown> | null = null;
  let ticketsNote = "";
  if (!accounts.size)
    ticketsNote = "No product account is linked to this firm, so its tickets cannot be found.";
  else {
    const mine = tickets.filter((row) => accounts.has(row.account_id));
    const waits = mine
      .filter(
        (row) =>
          row.created_at.slice(0, 10) >= start &&
          row.created_at.slice(0, 10) <= asOf &&
          row.first_replied_at,
      )
      .map((row) => (Date.parse(row.first_replied_at!) - Date.parse(row.created_at)) / 3_600_000)
      .sort((a, b) => a - b);
    const median = waits.length
      ? waits.length % 2
        ? waits[(waits.length - 1) / 2]!
        : (waits[waits.length / 2 - 1]! + waits[waits.length / 2]!) / 2
      : null;
    ticketFigures = {
      opened: mine.filter(
        (row) => row.created_at.slice(0, 10) >= start && row.created_at.slice(0, 10) <= asOf,
      ).length,
      resolved: mine.filter(
        (row) =>
          row.resolved_at &&
          row.resolved_at.slice(0, 10) >= start &&
          row.resolved_at.slice(0, 10) <= asOf,
      ).length,
      open_at_end: mine.filter(
        (row) =>
          row.created_at.slice(0, 10) <= asOf &&
          (!row.resolved_at || row.resolved_at.slice(0, 10) > asOf),
      ).length,
      answered: waits.length,
      median_first_reply_hours: median === null ? null : Math.round(median * 10) / 10,
      slowest_first_reply_hours: waits.length ? Math.round(waits.at(-1)! * 10) / 10 : null,
    };
  }
  const money: Record<string, { opening: number; closing: number; moves: Record<string, number> }> =
    {};
  for (const row of movements.filter((item) => item.company_id === companyId)) {
    const entry = (money[row.currency] ??= { opening: 0, closing: 0, moves: {} });
    if (row.effective_on < start) entry.opening += row.cents / 100;
    if (row.effective_on <= asOf) entry.closing += row.cents / 100;
    if (row.effective_on >= start && row.effective_on <= asOf)
      entry.moves[row.kind] = (entry.moves[row.kind] ?? 0) + row.cents / 100;
  }
  for (const entry of Object.values(money)) {
    entry.opening = finRound(entry.opening);
    entry.closing = finRound(entry.closing);
    for (const key of Object.keys(entry.moves)) entry.moves[key] = finRound(entry.moves[key]!);
  }
  const asks = featureAsks.filter((ask) => ask.company_id === companyId);
  const inPeriod = asks.filter(
    (ask) => ask.recorded_at.slice(0, 10) >= start && ask.recorded_at.slice(0, 10) <= asOf,
  );
  const askedIds = new Set(asks.map((ask) => ask.request_id));
  const onboarding = onboardings
    .filter((row) => row.company_id === companyId)
    .sort((a, b) => a.starts_on.localeCompare(b.starts_on))
    .at(-1);
  return {
    period_start: start,
    period_end: end,
    as_of: asOf,
    seats_paid: seats,
    usage: csUsage(seats, logins),
    usage_read_on: todayIso(),
    signals: csSignals(
      seats,
      logins,
      next?.renews_on ?? null,
      next?.renewal_status ?? "",
      csLastContact(companyId),
    ).map((item) => ({ label: item.label, rule: item.rule, evidence: item.evidence })),
    money: Object.fromEntries(Object.entries(money).sort(([a], [b]) => a.localeCompare(b))),
    tickets: ticketFigures,
    tickets_note: ticketsNote,
    asks: {
      in_period: inPeriod.length,
      blockers: inPeriod.filter((ask) => ask.importance === "blocker").length,
      requests: [
        ...new Set(
          inPeriod
            .map((ask) => featureRequests.find((row) => row.id === ask.request_id)?.title ?? "")
            .filter(Boolean),
        ),
      ].sort(),
    },
    shipped: featureRequests
      .filter(
        (row) =>
          askedIds.has(row.id) &&
          row.status === "shipped" &&
          row.shipped_on &&
          row.shipped_on >= start &&
          row.shipped_on <= asOf,
      )
      .map((row) => ({ title: row.title, shipped_on: row.shipped_on! })),
    renewal:
      next && next.renews_on
        ? {
            renews_on: next.renews_on,
            notice_date: csNoticeDate(next),
            status: next.renewal_status ?? "",
          }
        : null,
    onboarding: onboarding
      ? {
          starts_on: onboarding.starts_on,
          live_on: onboarding.live_on,
          durations: csOnboardingView(onboarding).durations,
        }
      : null,
  };
}
function relReviewView(
  row: BusinessReviewRow,
  headers: Record<string, string | string[] | undefined>,
  full: boolean,
) {
  const base = {
    review_id: row.id,
    company_id: row.company_id,
    company_name: companies.find((item) => item.id === row.company_id)?.name ?? "",
    period_start: row.period_start,
    period_end: row.period_end,
    title: row.title,
    status: row.status,
    held_on: row.held_on,
    snapshot_at: row.snapshot_at,
    finalised_by_name: row.finalised_by ? nameOf(row.finalised_by) : "",
    finalised_at: row.finalised_at,
    created_by_name: nameOf(row.created_by),
    updated_at: row.updated_at,
  };
  if (!full) return base;
  return {
    ...base,
    snapshot: hasCap(headers, "revenue:read") ? row.snapshot : { ...row.snapshot, money: null },
    goals: row.goals,
    wins: row.wins,
    risks: row.risks,
    actions: row.actions,
    attendees: row.attendees,
    can_edit: hasCap(headers, "crm:write"),
  };
}

