/** dispatch.STAFF_BODY_BYTES, prospects.IMPORT_BODY_BYTES and the configured default. */
const BODY_FORM_BYTES = 16_384;
const BODY_STAFF_BYTES = 262_144;
const BODY_ROWS_BYTES = 4 * 1024 * 1024;
/** The routes whose table entry declares `body_bytes`: the ones that take rows. */
const BODY_ROW_ROUTES = new Set([
  "hq/leads/import",
  "hq/leads/verification/import",
  "hq/leads/bulk",
  "hq/companies/import",
  "hq/people/import",
  "hq/mail/lists/{list_id}/import",
  "hq/mail/lists/{list_id}/members/add",
  "hq/mail/campaigns/create",
  "hq/mail/campaigns/{campaign_id}/update",
  "hq/mail/sequences/{sequence_id}/enrol/preview",
  "hq/mail/sequences/{sequence_id}/enrol",
  "hq/exports/{kind}",
]);

function matchRoute(method: string, route: string) {
  // An exact route wins over a pattern, as in the service's route table: without this,
  // `hq/companies/imports` read as the company whose id is "imports".
  const exact = routes.find(
    (entry) => entry.method === method && !entry.pattern.includes("{") && entry.pattern === route,
  );
  if (exact) return { entry: exact, params: {} as Record<string, string> };
  for (const entry of routes) {
    if (entry.method !== method || !entry.pattern.includes("{")) continue;
    const regex = new RegExp(
      `^${entry.pattern.replace(/\{([a-z_]+)\}/g, "(?<$1>[A-Za-z0-9._-]{1,64})")}$`,
    );
    const found = route.match(regex);
    if (found) return { entry, params: { ...(found.groups ?? {}) } };
  }
  // Same route, other method → 405, mirroring the service.
  const sibling = routes.some((entry) => {
    if (!entry.pattern.includes("{")) return entry.pattern === route;
    const regex = new RegExp(
      `^${entry.pattern.replace(/\{([a-z_]+)\}/g, "[A-Za-z0-9._-]{1,64}")}$`,
    );
    return regex.test(route);
  });
  return sibling ? "method" : null;
}

const server = createServer((request, response) => {
  const url = new URL(request.url ?? "/", `http://127.0.0.1:${PORT}`);
  if (!url.pathname.startsWith(PREFIX)) {
    response.writeHead(404).end();
    return;
  }
  const route = url.pathname.slice(PREFIX.length).replace(/\/+$/, "");
  const chunks: Buffer[] = [];
  request.on("data", (chunk: Buffer) => chunks.push(chunk));
  request.on("end", () => {
    let body: Record<string, unknown> = {};
    const rawBody = Buffer.concat(chunks);
    try {
      body = chunks.length ? (JSON.parse(rawBody.toString("utf8")) as Record<string, unknown>) : {};
    } catch {
      body = {};
    }
    const query: Record<string, string> = {};
    url.searchParams.forEach((value, name) => {
      query[name] = value;
    });
    // The mailbox consent screen: approve at once and back to the portal's callback.
    if (request.method === "GET" && route === "mock/mailbox-consent") {
      const back = new URL(`${PORTAL_ORIGIN}/mail/mailboxes/callback`);
      back.searchParams.set("code", "mock-code");
      back.searchParams.set("state", query.state ?? "");
      response.writeHead(302, { location: back.toString() }).end();
      console.log(`[mock-hq] GET /${route} -> 302 consent`);
      return;
    }
    // The mock consent screen: approve at once and send the browser back to the portal.
    if (request.method === "GET" && route === "mock/consent") {
      const back = new URL(`${PORTAL_ORIGIN}/admin/integrations/calendar/callback`);
      back.searchParams.set("code", "mock-code");
      back.searchParams.set("state", query.state ?? "");
      response.writeHead(302, { location: back.toString() }).end();
      console.log(`[mock-hq] GET /${route} -> 302 consent`);
      return;
    }
    const answer = respond(
      request.method ?? "GET",
      route,
      query,
      body,
      request.headers,
      rawBody.length,
    );
    if (answer.status === FORWARD) {
      void forwardProduct(answer.body as Record<string, unknown>).then((forwarded) => {
        response
          .writeHead(forwarded.status, { "content-type": "application/json" })
          .end(JSON.stringify(forwarded.body));
        console.log(`[mock-hq] ${request.method} /${route} -> ${forwarded.status} (product)`);
      });
      return;
    }
    response
      .writeHead(answer.status, { "content-type": "application/json" })
      .end(JSON.stringify(answer.body));
    console.log(`[mock-hq] ${request.method} /${route} -> ${answer.status}`);
  });
});

