function respond(
  method: string,
  route: string,
  query: Record<string, string>,
  body: Record<string, unknown>,
  headers: Record<string, string | string[] | undefined>,
  bodyBytes = 0,
) {
  // Test-only, deliberately OUTSIDE the hq/ and public/ namespaces the parity test
  // mirrors: the real service has no reset, and this must never look like it does.
  if (method === "POST" && route === "mock/reset") {
    resetWorld();
    return ok({ reset: true });
  }
  // Test-only, as above: a second person approves the newest waiting request of a kind,
  // for a walk that has no second enrolled Owner to sign in as (the newbies have no
  // authenticator yet). It decides exactly as hq/approvals/{id}/approve would.
  if (method === "POST" && route === "mock/approve-pending") {
    const row = approvals.find(
      (candidate) =>
        candidate.kind === String(body.kind ?? "") && approvalStatus(candidate) === "pending",
    );
    const approver = row
      ? approvers(row.kind, row.requested_by, row.target_staff_id)[0]
      : undefined;
    if (!row || !approver || row.kind === "role_grant" || row.kind === "write_off")
      return refuse(404, "not_found");
    row.status = "approved";
    row.expires_at = hoursFromNowIso(APPROVAL_TTL_HOURS);
    row.decided_by = approver.id;
    row.decided_at = now();
    row.decision_note = String(body.note ?? "").slice(0, 400);
    audit("approval.approved", approver.id, "approval", row.id, row.decision_note, {
      kind: row.kind,
      summary: approvalSummary(row.kind, row.payload),
      requested_by: row.requested_by,
      executed: false,
    });
    return ok({ approval: approvalView(row) });
  }
  if (DEGRADED.has(route)) return refuse(503, "upstream_unavailable");
  const matched = matchRoute(method, route);
  if (matched === null) return refuse(404, "not_found");
  if (matched === "method") return refuse(405, "method_not_allowed");
  const { entry, params } = matched;
  if (entry.auth) {
    const found = caller(headers);
    if (!found) return refuse(401, "session_invalid");
    if (entry.capability && !capsFor(found.role).includes(entry.capability)) {
      return refuse(403, "forbidden", { required_capability: entry.capability });
    }
    if (entry.sudo && !(found.session.sudo_until && found.session.sudo_until > now())) {
      return refuse(403, "forbidden", { sudo_required: true });
    }
    if (method === "POST" && !headers["idempotency-key"]) {
      return refuse(400, "idempotency_key_required");
    }
    // The service reads a staff route's body under 256 KB, and only the routes that
    // carry rows under 4 MB. A mock that never counted bytes certified imports the
    // service would have refused as too large.
    const staffLimit = BODY_ROW_ROUTES.has(entry.pattern) ? BODY_ROWS_BYTES : BODY_STAFF_BYTES;
    if (bodyBytes > staffLimit)
      return refuse(413, "payload_too_large", { limit_bytes: staffLimit });
    const watched = method === "GET" ? WATCHED_READS[entry.pattern] : undefined;
    if (watched) {
      const refused = gateRead(found);
      if (refused) return refused;
      const answer = entry.handler({ method, route, params, query, body, headers });
      if (answer.status === 200)
        noteRead(found, watched[0], String(params[watched[1]] ?? ""), clientAddress(headers));
      return answer;
    }
  } else if (bodyBytes > BODY_FORM_BYTES) {
    // An anonymous route takes a form, not a file.
    return refuse(413, "payload_too_large", { limit_bytes: BODY_FORM_BYTES });
  }
  return entry.handler({ method, route, params, query, body, headers });
}

